// The customer rates a resolved ticket, once. Another organisation's ticket answers exactly like a missing one (null),
// so the lookup comes before every other check.
function rate(store, customer, id, score, { now = new Date() } = {}) {
  const t = getMyTicket(store, customer, id);
  if (!t) return null;
  if (!Number.isInteger(score) || score < 1 || score > 5) throw new Error('a rating is a whole number from 1 to 5');
