```js
'use strict';
// Nightly. For each agent: how many ratings their tickets received in the past seven days, and the average score.
// One row per agent per day (UTC), so a rerun replaces the row. Agents with no ratings get no row, and a ticket
// without an owner counts for nobody.

const WINDOW_DAYS = 7;
const DAY = 24 * 60 * 60 * 1000;

function weeklyCsatSummary(store, { now = new Date() } = {}) {
  const since = now.getTime() - WINDOW_DAYS * DAY;
  const asOf = now.toISOString().slice(0, 10);
  const byAgent = new Map();
  for (const t of store.listTickets()) {
    if (t.csat_score == null || !t.owner_id) continue;
    if (new Date(t.csat_rated_at).getTime() < since) continue;
    const acc = byAgent.get(t.owner_id) || { sum: 0, n: 0 };
    acc.sum += t.csat_score;
    acc.n += 1;
    byAgent.set(t.owner_id, acc);
  }
  const rows = [...byAgent].map(([agentId, { sum, n }]) => ({
    agent_id: agentId,
    as_of: asOf,
    ratings: n,
    average: Math.round((sum / n) * 100) / 100,
  }));
  rows.sort((a, b) => a.agent_id - b.agent_id);
  for (const row of rows) store.saveAgentSummary(row);
  return rows;
}

module.exports = { weeklyCsatSummary, WINDOW_DAYS };
```

